head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf76200";
scwin.fn_setOutOrdNo = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.fn_setOutOrdNo = scwin.tx_fn_setOutOrdNo;
        scwin.init_ctxDefaults();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf76200.onpageload' });
    }
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"authYn":"Y"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.ldMktTpCd, pageContext.psDepCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2'); } }, { id: "btn_openRegisterPop", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }, { id: "btn_setOutOrdNo", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $("input[name=hideChk]").bind("click", function() {
                const chkIndex = $("input[name=hideChk]").index($(this));
                const chk = $("input[name=newChk]").eq(chkIndex);
                const outputOrdNo = $("input[name=outputOrdNo]").eq(chkIndex);
                const originOutNo = $("input[name=originOutNo]").eq(chkIndex);
                if (chk.val() === "Y") {
                    chk.val("N");
                    outputOrdNo.attr("readonly", false);
                    outputOrdNo.val(originOutNo.val());
                    outputOrdNo.css("color", "#343434");
                } else {
                    chk.val("Y");
                    outputOrdNo.attr("readonly", true);
                    outputOrdNo.val("9999999999");
                    outputOrdNo.css("color", "#9e9e9e");
                }
        });
        $("input[name=outputOrdNo]").bind("keyup", async function(event) {
                const obj = $(this);
                if (obj.attr("readonly") === false || obj.attr("readonly") == null || obj.attr("readonly") == null) {
                    if (!(($c.util.getKeyCode(event) >= 48 && $c.util.getKeyCode(event) <= 57) || ($c.util.getKeyCode(event) >= 96 && $c.util.getKeyCode(event) <= 105) || event.keyCode === 35 || event.keyCode === 36 || event.keyCode === 37 || event.keyCode === 39 || event.keyCode === 8 || event.keyCode === 46) && (event.shiftKey === false)) {
                        await $c.win.alert('숫자만 입력하시기 바랍니다.');
                        $(this).val('');
                    }
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76200.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_relatedLawList_oncellclick
 * @description grd_relatedLawList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_relatedLawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_relatedLawList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_relatedLawList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: clickTr (인자 미해석) */
        scwin.openEditRlaw(r["sprtRoomNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_relatedLawList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_openRegisterPop_onclick
 * @description 「등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openRegisterPop_onclick = function(e){
    try {
        scwin.openRegisterPop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76200.btn_openRegisterPop_onclick' }); }
};

/**
 * @method
 * @name btn_setOutOrdNo_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_setOutOrdNo_onclick = function(e){
    try {
        scwin.fn_setOutOrdNo()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76200.btn_setOutOrdNo_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_setOutOrdNo
 * @description set Out Ord No 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_setOutOrdNo = async function () {
    const sbmOptions = {
        id: "tx_fn_setOutOrdNo",
        method: "post",
        action: "/ods/sprtroom.do?method=checkOrderDupl",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/sprtroom.do?method=checkOrderDupl",
        ref: "dma_loadListReq",
        target: "dlt_relatedLawList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name reload
 * @description reload 처리
 * @returns {void}
 * @hidden N
 */
scwin.reload = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), null);
};

/**
 * @method
 * @name openRegisterPop
 * @description open Register Pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.openRegisterPop = function () {
    const url = "/ods/sprtroom.do?method=registerRelatedLawForm&SCREN_ID=JLDODS76210.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "popup", type: "pageFramePopup", title: "관련법규등록", width: "1200px", height: "800px" }, {});
};

/**
 * @method
 * @name openEditRlaw
 * @description open Edit Rlaw 처리
 * @param {*} no no
 * @returns {void}
 * @hidden N
 */
scwin.openEditRlaw = function (no) {
    const url = "/ods/sprtroom.do?method=readNoticeDetail&sprtRoomNo=" + no + "&sprtRoomId=RLAW&SCREN_ID=JLDODS76220.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "popup", type: "pageFramePopup", title: "관련법규변경", width: "1200px", height: "800px" }, {});
};
// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
